-- İstanbul uzun açıklamaları, 2. parti (10 yer, TR + EN).
-- Üreten: data-pipeline/content/build_long_desc.py (kaynak: content/istanbul_long_descriptions.py).
-- Metinler kendi cümlelerimizdir; Vikipedi/Wikidata yalnızca bilgi kontrolü için kullanıldı.

update public.place_translations t
   set long_desc = v.long_desc
  from (values
  ('sultanahmet-meydani-hipodrom', 'tr', 'Bugünkü Sultanahmet Meydanı, Roma ve Bizans döneminde araba yarışlarının yapıldığı Hipodrom''un yerindedir. Septimius Severus döneminde başlanıp I. Konstantin zamanında büyütülen Hipodrom, imparatorların halkla buluştuğu şehrin kalbiydi; 532''deki Nika Ayaklanması da burada patlak verdi. Osmanlı döneminde meydan Atmeydanı olarak anıldı.

Meydanın ortasında Firavun III. Thutmosis''ten kalma ve 4. yüzyılda Mısır''dan getirilen Dikilitaş, antik Delfi''den getirilen Yılanlı Sütun ve taşları açıkta kalmış Örme Dikilitaş sıralanır. Kuzey ucundaki sekizgen Alman Çeşmesi, Alman İmparatoru II. Wilhelm''in ziyaretinin hatırasıdır. Sultanahmet Camii ve Türk ve İslam Eserleri Müzesi de meydanın iki yanındadır.'),
  ('sultanahmet-meydani-hipodrom', 'en', 'Today''s Sultanahmet Square occupies the site of the Hippodrome, where chariot races were held in Roman and Byzantine times. Begun under Septimius Severus and enlarged by Constantine the Great, it was the heart of the city where emperors met their people; the Nika riot of 532 broke out here. In Ottoman times the square was known as Atmeydanı, the Horse Square.

Along its centre stand the Egyptian Obelisk of Pharaoh Thutmose III, brought from Egypt in the 4th century, the Serpent Column from ancient Delphi and the rough stone Walled Obelisk. The octagonal German Fountain at the north end commemorates the visit of Kaiser Wilhelm II. The Blue Mosque and the Museum of Turkish and Islamic Arts line the two sides of the square.'),
  ('kapalicarsi', 'tr', 'Dünyanın en eski ve en büyük kapalı çarşılarından biri olan Kapalıçarşı, Fatih Sultan Mehmed''in fetihten kısa süre sonra yaptırdığı Cevahir Bedesteni''nin çevresinde büyüyerek oluştu. Yüzyıllar içinde eklenen hanlar ve sokaklarla bugün yaklaşık dört bin dükkânın bulunduğu, kendi içinde bir şehir gibi işleyen bir yapıya dönüştü.

Çarşının en eski bölümü olan İç Bedesten''de antika ve mücevherciler, çevresindeki sokaklarda halı, seramik, deri, aydınlatma ve kumaş dükkânları yoğunlaşır. Kaybolmaktan korkmayın; sokak adları meslek gruplarına göre verilmiştir ve her yön bir kapıya çıkar. Pazar günleri ve dini bayramların ilk günü kapalıdır; pazarlık burada gelenektir.'),
  ('kapalicarsi', 'en', 'One of the oldest and largest covered markets in the world, the Grand Bazaar grew up around the Cevahir Bedesten, a warehouse that Sultan Mehmed II built soon after the conquest. Over the centuries, inns and streets were added until it became a city within the city with around four thousand shops.

Antique dealers and jewellers cluster in the old Inner Bedesten, while the surrounding lanes are full of carpets, ceramics, leather, lamps and textiles. Don''t worry about getting lost: streets are named after the trades once practised there, and every direction ends at a gate. It is closed on Sundays and on the first day of religious holidays, and bargaining is part of the tradition.'),
  ('kucuk-ayasofya-camii', 'tr', 'İmparator I. Justinianus ve eşi Theodora''nın 527-536 yılları arasında Azizler Sergios ve Bakhos adına yaptırdığı bu kilise, Ayasofya''dan birkaç yıl önce tamamlandığı için halk arasında Küçük Ayasofya adını aldı. II. Bayezid döneminde, 15. yüzyılın sonunda Darüssaade Ağası Hüseyin Ağa tarafından camiye çevrildi.

Sekizgen planlı iç mekânı ve sütun başlıklarındaki ince taş işçiliği, İstanbul''un ayakta kalan en eski Bizans yapılarından birinde olduğunuzu hatırlatır. Avludaki eski medrese odaları bugün sakin bir çay bahçesi ve el sanatları atölyeleriyle çevrilidir. Sultanahmet''in kalabalığından birkaç dakikalık yürüyüşle uzaklaşmak için iyi bir duraktır.'),
  ('kucuk-ayasofya-camii', 'en', 'Built between 527 and 536 by Emperor Justinian I and Empress Theodora and dedicated to Saints Sergius and Bacchus, this church was finished a few years before Hagia Sophia, which is why it came to be called Little Hagia Sophia. In the late 15th century, under Bayezid II, it was converted into a mosque by the chief harem eunuch Hüseyin Agha.

Its octagonal interior and the finely carved column capitals remind you that this is one of the oldest Byzantine buildings still standing in Istanbul. The cells of the old madrasa around the courtyard now host a quiet tea garden and craft workshops. It is a good escape from the Sultanahmet crowds, just a few minutes'' walk away.'),
  ('kiz-kulesi', 'tr', 'Üsküdar Salacak açıklarındaki küçük bir kayalığın üzerinde yükselen Kız Kulesi''nin geçmişi antik çağa kadar uzanır. Bizans döneminde burada bir gözetleme kulesi vardı; bugünkü yapı büyük ölçüde Osmanlı döneminde yeniden inşa edildi ve deniz feneri, karantina istasyonu gibi pek çok işlev üstlendi. Kapsamlı bir restorasyonun ardından 2023''te müze olarak yeniden açıldı.

Bir kehanetten korunmak için buraya kapatılan prenses ile yılan efsanesi kulenin adının kaynağı olarak anlatılır. Kuleye Salacak ve Karaköy''den kalkan teknelerle gidilir; içeride kulenin tarihini anlatan sergiler ve Tarihi Yarımada''ya bakan teras bulunur. Salacak sahilinden gün batımında kule ve şehir siluetini izlemek İstanbul''un klasik keyiflerindendir.'),
  ('kiz-kulesi', 'en', 'Rising from a small rock off Salacak in Üsküdar, the Maiden''s Tower has a history reaching back to antiquity. There was a watchtower here in Byzantine times; the present building was largely rebuilt in the Ottoman era and served as a lighthouse, a quarantine station and more. After a thorough restoration it reopened as a museum in 2023.

Its name comes from the legend of a princess locked away here to escape a prophecy, only to be bitten by a snake. Boats run to the tower from Salacak and Karaköy; inside are exhibitions on its history and a terrace facing the historic peninsula. Watching the sunset over the tower and the old city skyline from the Salacak shore is a classic Istanbul pleasure.'),
  ('konstantinopolis-surlari', 'tr', 'Konstantinopolis''i yaklaşık bin yıl boyunca koruyan surlar, Haliç ve Marmara kıyılarını da çevreleyerek toplamda yirmi kilometreyi aşan bir savunma hattı oluşturuyordu. En ünlü bölümü, 5. yüzyılda II. Theodosius döneminde Marmara''dan Haliç''e kadar inşa edilen, hendek ve iki sıra duvardan oluşan kara surlarıdır. Şehir 1453''te Osmanlılar tarafından fethedilene kadar bu surlar pek az kez aşılabildi.

Yedikule''den Ayvansaray''a uzanan kara surları boyunca yürüyerek kuleleri, kapıları ve onarılmış bölümleri görebilirsiniz; Topkapı, Edirnekapı ve Belgradkapı en bilinen kapılardır. Bazı burçlar ve duvar üstleri korunmasız ve dik olduğundan tırmanmamak gerekir. Surlar, İstanbul''un tarihi alanlarıyla birlikte UNESCO Dünya Mirası listesindedir.'),
  ('konstantinopolis-surlari', 'en', 'For nearly a thousand years the walls of Constantinople protected the city, also running along the Golden Horn and the Sea of Marmara to form a defensive line of more than twenty kilometres. The most famous part is the land wall built in the 5th century under Theodosius II from the Marmara to the Golden Horn, with a moat and a double line of walls. Until the Ottoman conquest of 1453 these walls were breached only rarely.

Walking along the land walls from Yedikule to Ayvansaray you pass towers, gates and restored sections; Topkapı, Edirnekapı and Belgradkapı are the best-known gates. Some towers and wall tops are steep and unprotected, so avoid climbing them. Together with Istanbul''s other historic areas, the walls are a UNESCO World Heritage Site.'),
  ('aya-irini', 'tr', 'Topkapı Sarayı''nın birinci avlusunda, Ayasofya''nın hemen yanındaki Aya İrini, adını ''kutsal barış''tan alan ve kökeni 4. yüzyıla uzanan bir Bizans kilisesidir. 532''deki Nika Ayaklanması''nda yanan yapıyı I. Justinianus yeniden inşa ettirdi. İstanbul''un camiye çevrilmemiş ender Bizans kiliselerinden biridir; Osmanlı döneminde cephanelik olarak kullanıldı ve 19. yüzyılda eski silahların sergilendiği bir koleksiyona ev sahipliği yaptı.

Süslemesiz, yalın taş ve tuğla iç mekânı, apsisteki büyük haç mozaiği ve mükemmel akustiği ile çok etkileyicidir; bu nedenle zaman zaman konser ve sergilere de ev sahipliği yapar. Topkapı Sarayı gezisine başlamadan önce birinci avluda uğranabilecek bir duraktır.'),
  ('aya-irini', 'en', 'In the first courtyard of Topkapı Palace, right next to Hagia Sophia, stands Hagia Irene, a Byzantine church named for ''holy peace'' whose origins go back to the 4th century. After it burned in the Nika riot of 532, Justinian I had it rebuilt. It is one of the few Byzantine churches in Istanbul never converted into a mosque; the Ottomans used it as an armoury, and in the 19th century it housed a collection of antique weapons.

Its bare stone-and-brick interior, the large mosaic cross in the apse and its superb acoustics are deeply atmospheric, which is why it sometimes hosts concerts and exhibitions. It makes a good stop in the first courtyard before you start exploring Topkapı Palace.'),
  ('beylerbeyi-sarayi', 'tr', 'Sultan Abdülaziz''in emriyle Sarkis Balyan''ın 1863-1865 yıllarında Boğaz''ın Anadolu yakasına inşa ettiği Beylerbeyi Sarayı, padişahın yazlık sarayı ve yabancı devlet konuklarının ağırlandığı bir konuk sarayıydı. Burada konaklayan ünlü misafirler arasında Fransa İmparatoriçesi Eugénie de vardı. Sultan II. Abdülhamid hayatının son yıllarını bu sarayda geçirdi.

Dolmabahçe''ye göre daha küçük ve samimi olan saray, mermer cepheleri, havuzlu salonu ve Boğaz''a uzanan bahçeleriyle dikkat çeker; bahçedeki küçük deniz köşkleri ayrıca görülmeye değer. Ziyaret rehberli turla yapılır. Hemen önünden geçen 15 Temmuz Şehitler Köprüsü''nün altındaki sahil, sarayla birlikte güzel bir Boğaz yürüyüşü sunar.'),
  ('beylerbeyi-sarayi', 'en', 'Built for Sultan Abdülaziz by Sarkis Balyan between 1863 and 1865 on the Asian shore of the Bosphorus, Beylerbeyi Palace was the sultan''s summer residence and a guest palace for foreign dignitaries. Among the famous visitors who stayed here was Empress Eugénie of France. Sultan Abdülhamid II spent the last years of his life in this palace.

Smaller and more intimate than Dolmabahçe, it is known for its marble façades, a hall with an indoor pool and gardens reaching down to the water; the little seaside pavilions in the garden are also worth seeing. Visits are by guided tour. The shoreline beneath the nearby Bosphorus bridge makes for a lovely waterside walk combined with the palace.'),
  ('ciragan-sarayi', 'tr', 'Beşiktaş ile Ortaköy arasındaki Çırağan Sarayı, Sultan Abdülaziz döneminde Balyan ailesinin mimarlarına yaptırılan ve 1871''de tamamlanan görkemli bir Boğaz sarayıdır. Tahttan indirilen V. Murad uzun yıllar burada yaşamak zorunda kaldı. 1909''da Meclis-i Mebusan''a tahsis edilen saray, 1910''daki büyük yangında neredeyse tamamen harap oldu.

Uzun yıllar harabe olarak kalan yapı, 20. yüzyılın sonlarında aslına uygun cephesiyle restore edilerek bir otelin parçası hâline getirildi. Bu yüzden içi müze olarak gezilemez; ancak deniz tarafındaki mermer cephesi Boğaz vapurlarından ve Ortaköy yönünden çok etkileyici görünür. Hemen arkasındaki Yıldız Parkı ile birlikte gezilebilir.'),
  ('ciragan-sarayi', 'en', 'Between Beşiktaş and Ortaköy, Çırağan Palace is a grand Bosphorus palace built for Sultan Abdülaziz by architects of the Balyan family and completed in 1871. The deposed Sultan Murad V was confined here for many years. Assigned to the Ottoman parliament in 1909, the palace was almost completely gutted by a great fire in 1910.

After standing as a ruin for decades, it was restored with its original façade in the late 20th century and became part of a hotel, so the interior cannot be visited as a museum. Its marble seafront façade, however, is impressive seen from Bosphorus ferries or from the Ortaköy side. It pairs well with Yıldız Park just behind it.'),
  ('kinaliada', 'tr', 'Prens Adaları''nın İstanbul''a en yakın olanı ve vapurun ilk uğradığı ada olan Kınalıada, Yunanca adı Proti''de de ''ilk'' anlamını taşır. Türkçe adını, yamaçlarındaki kızıl renkli topraktan alır. Bizans döneminde sürgün edilen imparatorlar ve soylular burada manastırlarda yaşamıştır; ada uzun süre Ermeni toplumunun sevdiği bir yazlık oldu.

Diğer adalara göre daha az ağaçlıktır ama kıyıları boyunca neredeyse her yerden denize girilebilir. İskeleden yürüyerek adanın tepesindeki manastıra çıkabilir, Marmara ve İstanbul manzarasının tadını çıkarabilirsiniz. Kısa ve sakin bir ada gezisi için iyi bir seçimdir; Büyükada''ya gidip dönerken de uğranabilir.'),
  ('kinaliada', 'en', 'The closest of the Princes'' Islands to Istanbul and the first stop for the ferry, Kınalıada''s Greek name, Proti, also means ''first''. Its Turkish name comes from the reddish, henna-coloured soil of its slopes. Exiled Byzantine emperors and nobles lived in monasteries here, and the island later became a favourite summer retreat of the Armenian community.

It has fewer trees than the other islands, but you can swim from almost anywhere along its shores. From the pier you can walk up to the monastery on the hilltop and enjoy views over the Marmara and the city. It is a good choice for a short, quiet island trip, or a stop on the way to or from Büyükada.'),
  ('sehzade-camii', 'tr', 'Kanuni Sultan Süleyman, 1543''te genç yaşta hayatını kaybeden oğlu Şehzade Mehmed''in anısına bu camiyi Mimar Sinan''a yaptırdı. 1543-1548 yılları arasında inşa edilen cami, Sinan''ın ''çıraklık eserim'' dediği ve ilk büyük selatin camisidir. Merkezi kubbenin dört yarım kubbeye yaslandığı simetrik planıyla sonraki pek çok camiye örnek oldu.

Geniş avlusu, şadırvanı ve kalabalıktan uzak sakin havasıyla Şehzadebaşı''nda keyifli bir duraktır. Bahçedeki türbeler arasında Şehzade Mehmed''in çinilerle bezeli türbesi özellikle dikkat çeker. Bozdoğan Kemeri ve Süleymaniye''ye yürüme mesafesindedir.'),
  ('sehzade-camii', 'en', 'Suleiman the Magnificent had this mosque built by Mimar Sinan in memory of his son Prince Mehmed, who died young in 1543. Constructed between 1543 and 1548, it is the first great imperial mosque by Sinan, who called it his ''apprentice work''. Its symmetrical plan, with the central dome resting on four half-domes, became a model for many later mosques.

With its broad courtyard, ablution fountain and calm atmosphere away from the crowds, it is a pleasant stop in Şehzadebaşı. Among the tombs in the garden, Prince Mehmed''s tile-decorated tomb is especially striking. The Valens Aqueduct and the Süleymaniye Mosque are within walking distance.')
  ) v(slug, lang, long_desc)
  join public.places p on p.slug = v.slug
 where t.place_id = p.id and t.lang = v.lang;
